/** Real native source geometry/selection/writes/custody/codec scenarios. Runtime is owned by integration. */
public final class WorldshaperGameTests {
    private static final String STRUCTURE="create_test:reservoir";
    private static final BlockPos P=new BlockPos(4,4,4),TARGET=P.offset(0,1,5);
    private static final Map<UUID,Predicate<BlockPos>> VETO=new ConcurrentHashMap<>();
    private static final Map<UUID,Runnable> CALLBACK=new ConcurrentHashMap<>();
    static {PlayerBlockBreakEvents.BEFORE.register((level,player,pos,state,entity)->{var action=CALLBACK.remove(player.getUUID());if(action!=null)action.run();var veto=VETO.get(player.getUUID());return veto==null||!veto.test(pos);});}
    private static NativeSurvivalTestPlayer player(GameTestHelper h){return NativeSurvivalTestPlayer.join(h,Vec3.atBottomCenterOf(h.absolutePos(P)));}
    private static ItemStack tool(){var stack=new ItemStack(AllItems.WORLDSHAPER);stack.set(DataComponents.CUSTOM_NAME,Component.literal("Original Worldshaper"));return stack;}
    private static ItemStack settings(TerrainTools mode){var result=tool();WorldshaperItem.configureSettings(result,PlacementPatterns.Solid,TerrainBrushes.Cuboid,1,1,1,mode,PlacementOptions.Merged);return result;}
    private static void lookForward(ServerPlayer p){p.setXRot(0);p.setYRot(0);}
    private static void equip(ServerPlayer p,ItemStack stack){p.setItemInHand(InteractionHand.MAIN_HAND,stack);lookForward(p);}
    private static BlockHitResult hit(GameTestHelper h){var target=h.absolutePos(TARGET);return new BlockHitResult(Vec3.atCenterOf(target).add(0,0,-.5),Direction.NORTH,target,false);}
    private static boolean activate(GameTestHelper h,ServerPlayer p,ItemStack stack,BlockState state){return AllItems.WORLDSHAPER.activate(h.getLevel(),p,stack,state,hit(h),null);}
    private static List<BlockPos> positions(Brush brush,GameTestHelper h){return new ArrayList<>(brush.addToGlobalPositions(h.getLevel(),BlockPos.ZERO,Direction.UP,new ArrayList<>(),TerrainTools.Fill));}
    private static void refused(GameTestHelper h,Runnable operation){boolean refused=false;try{operation.run();}catch(IllegalArgumentException expected){refused=true;}h.assertTrue(refused,"Source GUI bounds are rejected before publishing native settings");}
    @GameTest(structure=STRUCTURE) public void actualNativeSwingHookPreservesOriginalSourceSuppression(GameTestHelper h){try(var f=player(h)){var p=f.player();equip(p,tool());h.assertFalse(p.swing(InteractionHand.MAIN_HAND,net.minecraft.world.item.component.SwingAnimation.DEFAULT,true),"Genuine native swing is cancelled through the original source item hook");h.assertFalse(p.isSwinging(),"Source does not fabricate a swing state before separate actual recoil");p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.STICK));h.assertTrue(p.swing(InteractionHand.MAIN_HAND,net.minecraft.world.item.component.SwingAnimation.DEFAULT,true)&&p.isSwinging(),"Ordinary original native item still swings");}h.succeed();}
    @GameTest(structure=STRUCTURE) public void nativeSafeSignConfigurationRepaintsSameStateOnlyAfterActualProtectionAcceptance(GameTestHelper h){try(var f=player(h)){var p=f.player();h.setBlock(TARGET.below(),Blocks.STONE);h.setBlock(TARGET,Blocks.OAK_SIGN);var sign=(SignBlockEntity)h.getLevel().getBlockEntity(h.absolutePos(TARGET));var lines=List.<Component>of(Component.literal("Original text"),Component.empty(),Component.empty(),Component.empty());sign.setText(new SignText(lines,lines,DyeColor.BLUE,true),SignTextSlot.FRONT);var stack=tool();equip(p,stack);h.assertTrue(ZapperInteractionHandler.trySelect(stack,p)&&stack.has(AllDataComponents.SHAPER_BLOCK_DATA),"Actual source ray captures native safe sign configuration");var data=stack.get(AllDataComponents.SHAPER_BLOCK_DATA).copy();sign.setText(SignText.EMPTY,SignTextSlot.FRONT);var pos=h.absolutePos(TARGET);VETO.put(p.getUUID(),pos::equals);try{TerrainTools.Place.run(h.getLevel(),List.of(pos),Direction.NORTH,sign.getBlockState(),data,p);}finally{VETO.remove(p.getUUID());}h.assertTrue(h.getLevel().getBlockEntity(pos)==sign&&!sign.getText(SignTextSlot.FRONT).hasMessage(false),"Real same-state veto retains actual sign owner and its old configuration");TerrainTools.Place.run(h.getLevel(),List.of(pos),Direction.NORTH,sign.getBlockState(),data,p);h.assertTrue(h.getLevel().getBlockEntity(pos)==sign&&sign.getText(SignTextSlot.FRONT).getMessages(false).getFirst().getString().equals("Original text")&&sign.getText(SignTextSlot.FRONT).hasGlowingText(),"Original source same-state painting applies real selected sign text without replacing its native owner");}h.succeed();}
    @GameTest(structure=STRUCTURE) public void actualSingletonAndNativeComponentsKeepPinnedRegistryIds(GameTestHelper h){h.assertValueEqual(BuiltInRegistries.ITEM.getKey(AllItems.WORLDSHAPER),Create.asResource("handheld_worldshaper"),"Original registered source singleton");h.assertValueEqual(tool().getMaxStackSize(),1,"Pinned source tool does not stack");h.assertValueEqual(tool().getRarity(),Rarity.EPIC,"Pinned source rarity");for(var id:List.of("placement_pattern","shaper_brush","shaper_brush_params","shaper_placement_options","shaper_tool","shaper_block_used","shaper_block_data"))h.assertTrue(BuiltInRegistries.DATA_COMPONENT_TYPE.containsKey(Create.asResource(id)),"Source component remains registered: "+id);h.succeed();}
    @GameTest(structure=STRUCTURE) public void actualNativeItemCodecAndRegistryStreamPreserveSettingsAndNamedOriginalTool(GameTestHelper h){var stack=settings(TerrainTools.Place);stack.set(AllDataComponents.SHAPER_BLOCK_USED,Blocks.OAK_STAIRS.defaultBlockState().setValue(StairBlock.FACING,Direction.EAST));var data=new CompoundTag();data.putString("Configuration","original");stack.set(AllDataComponents.SHAPER_BLOCK_DATA,data);var ops=h.getLevel().registryAccess().createSerializationContext(NbtOps.INSTANCE);var restored=ItemStack.CODEC.parse(ops,ItemStack.CODEC.encodeStart(ops,stack).getOrThrow()).getOrThrow();h.assertTrue(ItemStack.matches(stack,restored),"Actual native item save retains every source setting and original component");var buffer=new RegistryFriendlyByteBuf(Unpooled.buffer(),h.getLevel().registryAccess());try{ItemStack.STREAM_CODEC.encode(buffer,stack);h.assertTrue(ItemStack.matches(stack,ItemStack.STREAM_CODEC.decode(buffer))&&buffer.readableBytes()==0,"Real registry stream preserves all source components without trailing bytes");}finally{buffer.release();}h.succeed();}
    @GameTest(structure=STRUCTURE) public void sourceCuboidHasAll32768PositionsWithExactEvenAsymmetry(GameTestHelper h){var brush=new CuboidBrush();brush.set(32,32,32);var positions=positions(brush,h);h.assertValueEqual(positions.size(),32768,"Original source maximum32 cubed");h.assertTrue(new HashSet<>(positions).size()==32768&&positions.contains(new BlockPos(-15,-15,-15))&&positions.contains(new BlockPos(16,16,16))&&!positions.contains(new BlockPos(-16,0,0)),"Source even brush bias and unique immutable offsets");h.succeed();}
    @GameTest(structure=STRUCTURE) public void sourceSphereAndCylinderKeepIndependentGeometricCensus(GameTestHelper h){var sphere=new SphereBrush();sphere.set(1,1,1);h.assertValueEqual(positions(sphere,h).size(),19,"Pinned radius1 includes face and edge neighbours but excludes corners");sphere.set(0,1,1);h.assertValueEqual(positions(sphere,h),List.of(BlockPos.ZERO),"Source zero radius is one real cell");var cylinder=new CylinderBrush();cylinder.set(1,3,1);var cells=positions(cylinder,h);h.assertTrue(cells.size()==27&&cells.contains(new BlockPos(1,-1,1))&&cells.contains(new BlockPos(-1,1,-1)),"Pinned radius1 uses nine cells in each of three centred layers");h.succeed();}
    @GameTest(structure=STRUCTURE) public void sourcePlacementOffsetsRespectPositiveNegativeEvenFaces(GameTestHelper h){var b=new CuboidBrush();b.set(4,2,6);h.assertValueEqual(b.getOffset(Vec3.ZERO,Direction.EAST,PlacementOptions.Attached),new BlockPos(2,0,0),"Source positive even attachment");h.assertValueEqual(b.getOffset(Vec3.ZERO,Direction.WEST,PlacementOptions.Attached),new BlockPos(-3,0,0),"Source negative even attachment");h.assertValueEqual(b.getOffset(Vec3.ZERO,Direction.UP,PlacementOptions.Inserted),new BlockPos(0,-1,0),"Source insertion reverses clicked face");h.assertValueEqual(b.getOffset(Vec3.ZERO,Direction.DOWN,PlacementOptions.Merged),BlockPos.ZERO,"Source merged placement stays at actual hit");h.succeed();}
    @GameTest(structure=STRUCTURE) public void checkerboardsPartitionNegativeAndPositiveWorldCoordinatesExactly(GameTestHelper h){var original=BlockPos.betweenClosedStream(-2,-1,-2,2,1,2).map(BlockPos::immutable).toList();var a=new ArrayList<>(original);var b=new ArrayList<>(original);var stack=tool();stack.set(AllDataComponents.PLACEMENT_PATTERN,PlacementPatterns.Checkered);PlacementPatterns.applyPattern(a,stack,RandomSource.create(5));stack.set(AllDataComponents.PLACEMENT_PATTERN,PlacementPatterns.InverseCheckered);PlacementPatterns.applyPattern(b,stack,RandomSource.create(5));var union=new HashSet<>(a);union.addAll(b);h.assertTrue(Collections.disjoint(a,b)&&union.equals(new HashSet<>(original))&&a.stream().allMatch(p->(p.getX()+p.getY()+p.getZ())%2!=0),"Original checker polarity and Java negative remainder partition exact native positions");h.succeed();}
    @GameTest(structure=STRUCTURE) public void chancePatternsRetainSourceRandomShortCircuitConsumption(GameTestHelper h){var original=BlockPos.betweenClosedStream(0,0,0,63,0,0).map(BlockPos::immutable).toList();for(var pattern:List.of(PlacementPatterns.Chance25,PlacementPatterns.Chance50,PlacementPatterns.Chance75)){var actual=new ArrayList<>(original);var expected=new ArrayList<BlockPos>();var a=RandomSource.create(448822);var b=RandomSource.create(448822);for(var pos:original){boolean remove=switch(pattern){case Chance25->b.nextBoolean()||b.nextBoolean();case Chance50->b.nextBoolean();case Chance75->b.nextBoolean()&&b.nextBoolean();default->false;};if(!remove)expected.add(pos);}var stack=tool();stack.set(AllDataComponents.PLACEMENT_PATTERN,pattern);PlacementPatterns.applyPattern(actual,stack,a);h.assertTrue(actual.equals(expected)&&a.nextLong()==b.nextLong(),"Original random sequence, short circuit and actual affected cells: "+pattern);}h.succeed();}
    @GameTest(structure=STRUCTURE) public void malformedConfigurationRefusesBeforeMutatingOriginalTool(GameTestHelper h){var stack=settings(TerrainTools.Place);var original=stack.copy();refused(h,()->WorldshaperItem.configureSettings(stack,PlacementPatterns.Solid,TerrainBrushes.Cuboid,33,1,1,TerrainTools.Fill,PlacementOptions.Merged));refused(h,()->new ConfigureWorldshaperPacket(InteractionHand.MAIN_HAND,PlacementPatterns.Solid,TerrainBrushes.Surface,2,2,1,TerrainTools.Replace,PlacementOptions.Merged));refused(h,()->new ConfigureWorldshaperPacket(InteractionHand.MAIN_HAND,PlacementPatterns.Solid,TerrainBrushes.Cluster,2,1,1,TerrainTools.Fill,PlacementOptions.Merged));h.assertTrue(ItemStack.matches(stack,original),"Rejected oversized/unsupported/native connectivity settings retain original tool byte semantics");h.succeed();}
    @GameTest(structure=STRUCTURE) public void actualPacketRoundtripAppliesOnlyToCurrentlyHeldSourceTool(GameTestHelper h){try(var f=player(h)){var p=f.player();var packet=new ConfigureWorldshaperPacket(InteractionHand.OFF_HAND,PlacementPatterns.InverseCheckered,TerrainBrushes.Sphere,3,1,1,TerrainTools.Replace,PlacementOptions.Attached);var buffer=new RegistryFriendlyByteBuf(Unpooled.buffer(),h.getLevel().registryAccess());try{ConfigureWorldshaperPacket.STREAM_CODEC.encode(buffer,packet);var decoded=ConfigureWorldshaperPacket.STREAM_CODEC.decode(buffer);var ordinary=new ItemStack(Items.STICK);p.setItemInHand(InteractionHand.OFF_HAND,ordinary);decoded.handle(p);h.assertFalse(ordinary.has(AllDataComponents.SHAPER_BRUSH),"Stale held capability never configures ordinary native item");var stack=tool();p.setItemInHand(InteractionHand.OFF_HAND,stack);decoded.handle(p);h.assertTrue(stack.get(AllDataComponents.SHAPER_BRUSH)==TerrainBrushes.Sphere&&stack.get(AllDataComponents.PLACEMENT_PATTERN)==PlacementPatterns.InverseCheckered&&stack.get(AllDataComponents.SHAPER_BRUSH_PARAMS).equals(new BlockPos(3,1,1)),"Actual offhand packet updates source tool using real native settings");}finally{buffer.release();}}h.succeed();}
    @GameTest(structure=STRUCTURE) public void actualSelectionNormalizesStairsLeavesAndWaterlogging(GameTestHelper h){try(var f=player(h)){var p=f.player();var stack=tool();equip(p,stack);h.setBlock(TARGET,Blocks.OAK_STAIRS.defaultBlockState().setValue(StairBlock.SHAPE,StairsShape.INNER_LEFT).setValue(StairBlock.WATERLOGGED,true));h.assertTrue(ZapperInteractionHandler.trySelect(stack,p),"Real server ray selects source stairs");var selected=stack.get(AllDataComponents.SHAPER_BLOCK_USED);h.assertTrue(selected.is(Blocks.OAK_STAIRS)&&selected.getValue(StairBlock.SHAPE)==StairsShape.STRAIGHT&&!selected.getValue(StairBlock.WATERLOGGED),"Original stair shape/water normalization");h.setBlock(TARGET,Blocks.OAK_LEAVES.defaultBlockState().setValue(LeavesBlock.PERSISTENT,false));h.assertTrue(ZapperInteractionHandler.trySelect(stack,p)&&stack.get(AllDataComponents.SHAPER_BLOCK_USED).getValue(LeavesBlock.PERSISTENT),"Actual selected source leaves become persistent");}h.succeed();}
    @GameTest(structure=STRUCTURE) public void chestPortalAndTwoPartSelectionsNeverCloneOriginalCargoOrAuthority(GameTestHelper h){try(var f=player(h)){var p=f.player();var stack=tool();equip(p,stack);h.setBlock(TARGET,Blocks.CHEST);var chest=(ChestBlockEntity)h.getLevel().getBlockEntity(h.absolutePos(TARGET));var diamonds=new ItemStack(Items.DIAMOND,7);diamonds.set(DataComponents.CUSTOM_NAME,Component.literal("Original chest cargo"));chest.setItem(0,diamonds);h.assertFalse(ZapperInteractionHandler.trySelect(stack,p),"Source unsafe chest selection refuses");h.assertTrue(chest.getItem(0)==diamonds&&diamonds.getCount()==7&&!stack.has(AllDataComponents.SHAPER_BLOCK_DATA),"Original real chest stock stays in its native owner");h.setBlock(TARGET,Blocks.NETHER_PORTAL);h.assertFalse(ZapperInteractionHandler.trySelect(stack,p),"Native portal is not a placeable source material");h.setBlock(TARGET,Blocks.OAK_DOOR);h.assertFalse(ZapperInteractionHandler.trySelect(stack,p),"Source two-part door selection refuses");h.assertFalse(stack.has(AllDataComponents.SHAPER_BLOCK_USED),"No rejected selection publishes a source block");}h.succeed();}
    @GameTest(structure=STRUCTURE) public void sourceSelectionDoesNotRepeatOrOperateWhileCrouchedOrSpectating(GameTestHelper h){try(var f=player(h)){var p=f.player();var stack=tool();equip(p,stack);h.setBlock(TARGET,Blocks.STONE);h.assertTrue(ZapperInteractionHandler.trySelect(stack,p),"First actual selection changes real components");h.assertFalse(ZapperInteractionHandler.trySelect(stack,p),"Identical source state and metadata are not republished");p.setShiftKeyDown(true);h.setBlock(TARGET,Blocks.DIRT);h.assertFalse(ZapperInteractionHandler.trySelect(stack,p),"Original source Shift suppresses material selection");p.setShiftKeyDown(false);p.setGameMode(GameType.SPECTATOR);h.assertFalse(ZapperInteractionHandler.trySelect(stack,p),"Real spectator cannot select source material");h.assertTrue(stack.get(AllDataComponents.SHAPER_BLOCK_USED).is(Blocks.STONE),"Refused modes retain exact previous actual selection");}h.succeed();}
    @GameTest(structure=STRUCTURE) public void survivalWorldshaperRetainsSourceNoInventoryDebitSemantics(GameTestHelper h){try(var f=player(h)){var p=f.player();var stack=settings(TerrainTools.Place);stack.set(AllDataComponents.SHAPER_BLOCK_USED,Blocks.DIAMOND_BLOCK.defaultBlockState());equip(p,stack);var stock=new ItemStack(Items.DIAMOND,7);p.getInventory().setItem(9,stock);h.setBlock(TARGET,Blocks.STONE);h.assertTrue(AllItems.WORLDSHAPER.use(h.getLevel(),p,InteractionHand.MAIN_HAND).consumesAction(),"Actual native survival use retains the pinned source action");h.assertBlockPresent(Blocks.DIAMOND_BLOCK,TARGET);h.assertTrue(!p.hasInfiniteMaterials()&&stock.getCount()==7&&stack.getCount()==1&&stack.getDamageValue()==0,"Source Worldshaper has no item debit/creative flag gate; no fabricated abilities or stock");h.assertTrue(p.getCooldowns().isOnCooldown(stack),"Real source two-tick reload applies to actual stack");}h.succeed();}
    @GameTest(structure=STRUCTURE) public void actualFillPlaceReplaceClearAndOverlayKeepTheirOriginalWorldRules(GameTestHelper h){try(var f=player(h)){var p=f.player();var level=h.getLevel();var a=h.absolutePos(TARGET);var b=a.east();var c=a.east(2);h.setBlock(TARGET,Blocks.STONE);h.setBlock(TARGET.east(),Blocks.AIR);TerrainTools.Fill.run(level,List.of(a,b),Direction.NORTH,Blocks.GOLD_BLOCK.defaultBlockState(),null,p);h.assertTrue(level.getBlockState(a).is(Blocks.STONE)&&level.getBlockState(b).is(Blocks.GOLD_BLOCK),"Actual fill touches replaceable cells only");TerrainTools.Replace.run(level,List.of(a,c),Direction.NORTH,Blocks.DIRT.defaultBlockState(),null,p);h.assertTrue(level.getBlockState(a).is(Blocks.DIRT)&&level.getBlockState(c).isAir(),"Actual replace keeps air");TerrainTools.Overlay.run(level,List.of(a),Direction.EAST,Blocks.STONE.defaultBlockState(),null,p);h.assertTrue(level.getBlockState(a.above()).is(Blocks.STONE),"Original shaped overlay places above even when hit face is horizontal");TerrainTools.Place.run(level,List.of(a,c),Direction.UP,Blocks.GOLD_BLOCK.defaultBlockState(),null,p);h.assertTrue(level.getBlockState(a).is(Blocks.GOLD_BLOCK)&&level.getBlockState(c).is(Blocks.GOLD_BLOCK),"Actual place handles both solid and air cells");TerrainTools.Clear.run(level,List.of(a,b,c,a.above()),Direction.UP,null,null,p);h.assertTrue(List.of(a,b,c,a.above()).stream().allMatch(pos->level.getBlockState(pos).isAir()),"Actual clear removes native cells");}h.succeed();}
    @GameTest(structure=STRUCTURE) public void nativeRemovalReleasesOriginalChestInventoryExactlyOnce(GameTestHelper h){try(var f=player(h)){var p=f.player();h.setBlock(TARGET,Blocks.CHEST);var chest=(ChestBlockEntity)h.getLevel().getBlockEntity(h.absolutePos(TARGET));var stack=new ItemStack(Items.DIAMOND,7);stack.set(DataComponents.CUSTOM_NAME,Component.literal("Original Zapper removal cargo"));chest.setItem(0,stack);var sample=stack.copy();var pos=h.absolutePos(TARGET);h.assertTrue(ZapperWorldAccess.write(h.getLevel(),p,pos,Blocks.AIR.defaultBlockState()),"Real native source clear succeeds");h.assertTrue(LoadedLevelAccess.blockEntity(h.getLevel(),pos)==null&&chest.isRemoved(),"Actual native BE owner retires");int released=h.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(pos).inflate(2)).stream().filter(item->ItemStack.isSameItemSameComponents(item.getItem(),sample)).mapToInt(item->item.getItem().getCount()).sum();h.assertValueEqual(released,7,"Native removal drops exact original component-bearing cargo once");h.assertFalse(ZapperWorldAccess.write(h.getLevel(),p,pos,Blocks.AIR.defaultBlockState()),"Repeated actual clear has no second publication");}h.succeed();}
    @GameTest(structure=STRUCTURE) public void realBreakVetoPreservesOriginalChestOwnerCargoAndMetadata(GameTestHelper h){try(var f=player(h)){var p=f.player();h.setBlock(TARGET,Blocks.CHEST);var chest=(ChestBlockEntity)h.getLevel().getBlockEntity(h.absolutePos(TARGET));var stack=new ItemStack(Items.DIAMOND,7);chest.setItem(0,stack);var pos=h.absolutePos(TARGET);VETO.put(p.getUUID(),pos::equals);try{TerrainTools.Place.run(h.getLevel(),List.of(pos),Direction.UP,Blocks.OAK_SIGN.defaultBlockState(),new CompoundTag(),p);}finally{VETO.remove(p.getUUID());}h.assertTrue(h.getLevel().getBlockEntity(h.absolutePos(TARGET))==chest&&chest.getItem(0)==stack&&stack.getCount()==7,"Actual Fabric veto retains native chest identity and every original item");h.assertBlockPresent(Blocks.CHEST,TARGET);}h.succeed();}
    @GameTest(structure=STRUCTURE) public void actualCallbackReplacementIsNeverOverwrittenByStaleSourceWrite(GameTestHelper h){try(var f=player(h)){var p=f.player();h.setBlock(TARGET,Blocks.STONE);var target=h.absolutePos(TARGET);CALLBACK.put(p.getUUID(),()->h.getLevel().setBlockAndUpdate(target,Blocks.CHEST.defaultBlockState()));try{h.assertFalse(ZapperWorldAccess.write(h.getLevel(),p,target,Blocks.GOLD_BLOCK.defaultBlockState()),"Real callback replacement invalidates captured source target");}finally{CALLBACK.remove(p.getUUID());}h.assertBlockPresent(Blocks.CHEST,TARGET);h.assertTrue(h.getLevel().getBlockEntity(h.absolutePos(TARGET)) instanceof ChestBlockEntity,"Actual callback owns fresh native BE");}h.succeed();}
    @GameTest(structure=STRUCTURE) public void flattenPairPreflightsBothActualVetoesBeforeAnyNativePublication(GameTestHelper h){try(var f=player(h)){var p=f.player();var first=h.absolutePos(TARGET);var second=first.above();h.setBlock(TARGET,Blocks.STONE);VETO.put(p.getUUID(),second::equals);try{h.assertFalse(ZapperWorldAccess.writePair(h.getLevel(),p,first,Blocks.DIRT.defaultBlockState(),second,Blocks.STONE.defaultBlockState()),"Actual second source edit veto stops complete Flatten step");}finally{VETO.remove(p.getUUID());}h.assertBlockPresent(Blocks.STONE,TARGET);h.assertBlockPresent(Blocks.AIR,TARGET.above());}h.succeed();}
    @GameTest(structure=STRUCTURE) public void absentNativeChunksNeverAcquireTicketsFromBrushReadOrWrite(GameTestHelper h){try(var f=player(h)){var p=f.player();var absent=new BlockPos(29000000,64,29000000);h.assertTrue(h.getLevel().getChunkSource().getChunkNow(absent.getX()>>4,absent.getZ()>>4)==null,"Real distant chunk starts absent");h.assertTrue(ZapperWorldAccess.read(h.getLevel(),absent).is(Blocks.BARRIER),"Source flood fill stops at actual missing data");h.assertFalse(ZapperWorldAccess.write(h.getLevel(),p,absent,Blocks.STONE.defaultBlockState()),"Real missing target refuses edit");var dynamic=new DynamicBrush(false);dynamic.set(3,0,0);h.assertTrue(dynamic.addToGlobalPositions(h.getLevel(),absent,Direction.UP,new ArrayList<>(),TerrainTools.Clear).isEmpty(),"Source dynamic brush cannot cross absent cells");h.assertTrue(h.getLevel().getChunkSource().getChunkNow(absent.getX()>>4,absent.getZ()>>4)==null,"No source helper creates an actual FULL chunk");}h.succeed();}
    @GameTest(structure=STRUCTURE) public void actualAdventureAndSpectatorModesCannotPublishNativeEdits(GameTestHelper h){try(var f=player(h)){var p=f.player();h.setBlock(TARGET,Blocks.STONE);for(var mode:List.of(GameType.ADVENTURE,GameType.SPECTATOR)){p.setGameMode(mode);h.assertFalse(ZapperWorldAccess.write(h.getLevel(),p,h.absolutePos(TARGET),Blocks.GOLD_BLOCK.defaultBlockState()),"Actual native mode refuses source edit: "+mode);h.assertBlockPresent(Blocks.STONE,TARGET);}}h.succeed();}
    @GameTest(structure=STRUCTURE) public void nativeSurfaceAndClusterSearchKeepOriginalMaterialAndConnectivityRules(GameTestHelper h){var center=h.absolutePos(TARGET);h.setBlock(TARGET,Blocks.STONE);h.setBlock(TARGET.east(),Blocks.DIRT);h.setBlock(TARGET.offset(1,0,1),Blocks.STONE);h.setBlock(TARGET.above(),Blocks.STONE);var surface=new DynamicBrush(true);surface.set(3,1,1);var exact=surface.addToGlobalPositions(h.getLevel(),center,Direction.NORTH,new ArrayList<>(),TerrainTools.Replace);h.assertTrue(exact.contains(center)&&exact.contains(center.above())&&!exact.contains(center.east())&&!exact.contains(center.offset(1,0,1)),"Source surface exact material does not cross dirt or leave selected face plane");var cluster=new DynamicBrush(false);cluster.set(3,0,0);var fuzzy=cluster.addToGlobalPositions(h.getLevel(),center,Direction.NORTH,new ArrayList<>(),TerrainTools.Replace);h.assertTrue(fuzzy.contains(center.east())&&fuzzy.contains(center.offset(1,0,1)),"Source fuzzy diagonal cluster reaches original mixed blocks");h.assertTrue(surface.redirectTool(TerrainTools.Overlay)==TerrainTools.Place,"Original surface overlay redirects actual painting to source place");h.succeed();}
    @GameTest(structure=STRUCTURE) public void flattenOfUniformNativeSurfacePreservesEveryOriginalCell(GameTestHelper h){var cells=new ArrayList<BlockPos>();for(int x=0;x<5;x++)for(int z=0;z<5;z++){var pos=TARGET.offset(x,0,z);h.setBlock(pos,Blocks.STONE);cells.add(h.absolutePos(pos));}try(var f=player(h)){FlattenTool.apply(h.getLevel(),cells,Direction.UP,f.player());for(var pos:cells)h.assertTrue(h.getLevel().getBlockState(pos).is(Blocks.STONE)&&h.getLevel().getBlockState(pos.above()).isAir(),"Original Gaussian flatten leaves a uniform actual surface unchanged");}h.succeed();}
}
